#'   try(vtb_infobasket_team_stats(season = 2026))
#' }
#' @export
#' @family VTB Functions
vtb_infobasket_team_stats <- function(season, tag = "vtb") {
  withr::local_options(list(scipen = 999, stringsAsFactors = FALSE))
  call <- rlang::current_env()
  raw <- .vtb_ib_get(
    "/Comp/GetTeamStats/{season}", ids = list(season = season),
    query = list(page = 0, tag = tag),
    call = call
  )
  .vtb_out("vtb_infobasket_team_stats", raw, "VTB Infobasket Team Stats from org.infobasket.su")
}

