#' @description
#' The competitions a club played in one season.
#'
#' Endpoint: `GET https://org.infobasket.su/Widget/GetTeamComps/{team_id}`
#' @param team_id Infobasket TeamID (team_id in the calendar, a box score or the v2 matches), e.g. 2650 (Lokomotiv
#'   Kuban).
#' @param season Season END year (2026 = 2025-26); the wrapper maps it to the season-level Infobasket CompID with
#'   vtb_infobasket_seasons (one extra request per tag, cached). Required.
#' @param lang Label language (en or ru). Most bodies carry both languages whatever is asked; the leader categories'
#'   labels follow it.
#' @param tag Competition tag scoping the profile: vtb (VTB United League, default), vtbyouth, wbc, wpremier or rfb.
#'   The season table is read for this tag.
#' @return
#' A `hoopR_data` tibble: The competitions a club played in one season. The columns are always these, in this order
#'   (sdv-py `vtb_infobasket_team_comps`); an empty valid answer raises `hoopR_no_data`, a valid body with no rows for
#'   this frame is a zero-row tibble:
#'
#' | col_name | type | description |
#' |:---|:---|:---|
#' | team_id | integer | Infobasket TeamID (2650 = Lokomotiv Kuban); the v2 teamId. Not a club-record id and not a registration id. |
#' | season | integer | Season END year (2026 = 2025-26): the season the request asked for, stamped by the runtime. |
#' | comp_id | integer | Competition id (the season or a stage of it). |
#' | comp_type | integer | Stage type code: 0 season, regular season or group; 10 playoff container; 5 and 7 playoff series; -5 seen in season lists. Meanings inferred from the stage names, unverified. |
#' | comp_sort | integer | Sort order among sibling stages. |
#' | level | integer | Depth of the competition in the tree (1 = season level). |
#' | comp_name_ru | character | Competition name, Russian ('Edinaya liga VTB' = 'VTB United League'). |
#' | comp_name_en | character | Stage name (e.g. 'Regular Season'), English. |
#' | parent_comp_id | integer | Unobserved: null in every sample, so its type and meaning are unconfirmed. |
#' @eval .intl_details(.vtb_infobasket_seasons_details, "vtb_infobasket_team_comps(season = 2026, team_id = 2650)")
#' @export
#' @family VTB Functions
vtb_infobasket_team_comps <- function(team_id, season, lang = "en", tag = "vtb") {
  withr::local_options(list(scipen = 999, stringsAsFactors = FALSE))
  call <- rlang::current_env()
  .vtb_lang_arg(lang, call = call)
  raw <- .vtb_ib_get(
    "/Widget/GetTeamComps/{team_id}", ids = list(team_id = team_id),
    query = list(format = "json", season = season, lang = lang, tag = tag),
    call = call
  )
  .vtb_out("vtb_infobasket_team_comps", raw, "VTB Infobasket Team Comps from org.infobasket.su")
}

#' @title
#' **Get VTB Infobasket Roster**
#' @description
#' A club's player roster in one season.
#'
#' Endpoint: `GET https://org.infobasket.su/Widget/TeamRoster/{team_id}`
#' @param team_id Infobasket TeamID (team_id in the calendar, a box score or the v2 matches), e.g. 2650 (Lokomotiv
#'   Kuban).
#' @param season Season END year (2026 = 2025-26); the wrapper maps it to the season-level Infobasket CompID with
#'   vtb_infobasket_seasons (one extra request per tag, cached). Required.
#' @param lang Label language (en or ru). Most bodies carry both languages whatever is asked; the leader categories'
#'   labels follow it.
#' @param tag Competition tag scoping the profile: vtb (VTB United League, default), vtbyouth, wbc, wpremier or rfb.
#'   The season table is read for this tag.
#' @return
#' A `hoopR_data` tibble: A club's player roster in one season. The columns are always these, in this order (sdv-py
#'   `vtb_infobasket_roster`); an empty valid answer raises `hoopR_no_data`, a valid body with no rows for this frame
#'   is a zero-row tibble:
#'
#' | col_name | type | description |
#' |:---|:---|:---|
#' | team_id | integer | Infobasket TeamID (2650 = Lokomotiv Kuban); the v2 teamId. Not a club-record id and not a registration id. |
#' | season | integer | Season END year (2026 = 2025-26): the season the request asked for, stamped by the runtime. |
#' | person_id | integer | Infobasket person id (PersonID): one person (player, coach or official) across clubs and seasons. Joins to /Widget/PlayerPage/\{personId\} (players) and /Widget/CoachPage/\{personId\} (coaches). |
#' | player_number | integer | Shirt number as an integer (-1 when none). |
#' | display_number | character | Shirt number as displayed ('0' and '00' differ). |
#' | is_captain | logical | 1 for the team captain, else 0. |
#' | birth_date | character | Birth date (ISO 8601 date) of a player: public bio, kept; coaches' and officials' birth data is never output. |
#' | pos_id | integer | Position code: players 1 point guard, 2 shooting guard, 3 small forward, 4 power forward, 5 centre; coaches 1000 head coach, 1001 assistant; officials 101-103 referees, 104 commissioner, 111-123 table officials (exact roles unverified). |
#' | position | character | Playing position: a record (PlayerPage) or its English name (TeamRoster). |
#' | nationality_code | character | Nationality, ISO 3166 alpha-2. |
#' | country_code | character | Nationality, ISO 3166 alpha-2. |
#' | country_code_ioc | character | Nationality code: ISO 3166 alpha-2 in most rows ('RU', 'US'), IOC alpha-3 in some ('BLR'). |
#' | country_name | character | Nationality, English country name. |
#' | rank | integer | Unobserved: the roster sends an empty string for every player and coach (null here); the field belongs to the leader lists (best_players), so its meaning on the roster is unconfirmed. |
#' | height | integer | Height in centimetres. |
#' | weight | integer | Weight in kilograms. |
#' | is_active | logical | True while the person is on the current roster. |
#' | active_status | character | Roster status text ('Accepted'), empty otherwise. |
#' | person_last_name_ru | character | Last name, Russian. |
#' | person_last_name_en | character | Last name, English. |
#' | person_first_name_ru | character | First name, Russian. |
#' | person_first_name_en | character | First name, English. |
#' | person_full_name_ru | character | Full name, 'Last First', Russian. |
#' | person_full_name_en | character | Full name, 'Last First', English. |
#' | person_gender | integer | Person gender: 1 on every sampled (male) person. |
#' @inherit vtb_infobasket_seasons details
#' @examples
#' \donttest{
#'   try(vtb_infobasket_roster(season = 2026, team_id = 2650))
#' }
#' @export
#' @family VTB Functions
vtb_infobasket_roster <- function(team_id, season, lang = "en", tag = "vtb") {
  withr::local_options(list(scipen = 999, stringsAsFactors = FALSE))
  call <- rlang::current_env()
  .vtb_lang_arg(lang, call = call)
  raw <- .vtb_ib_get(
    "/Widget/TeamRoster/{team_id}", ids = list(team_id = team_id),
    query = list(format = "json", season = season, lang = lang, tag = tag),
    call = call
  )
  .vtb_out("vtb_infobasket_roster", raw, "VTB Infobasket Roster from org.infobasket.su")
}

